// 1. Obtener la respuesta generada por el agente de IA
// Busca automáticamente en los campos comunes donde los nodos de IA devuelven texto
const aiResponse = $input.item.json.output || $input.item.json.text || $input.item.json.response || "";

// 2. Extraer datos clave del mensaje original desde el nodo Webhook
const webhookData = $("Webhook").item.json;
const conversationId = webhookData.body.conversation.id;
const accountId = webhookData.body.account.id;
const channel = webhookData.body.conversation.channel;

// 3. Formatear el texto para canales de Meta (WhatsApp, Instagram, Messenger)
let formattedText = aiResponse;

// Convertir negritas de Markdown (**texto**) a formato Meta (*texto*)
formattedText = formattedText.replace(/\*\*(.*?)\*\*/g, '*$1*');

// Convertir enlaces hipertextuales [Texto](URL) a texto plano "Texto: URL"
formattedText = formattedText.replace(/\[(.*?)\]\((.*?)\)/g, '$1: $2');

// 4. Retornar los datos listos para el nodo HTTP Request hacia Chatwoot
return {
  json: {
    formatted_response: formattedText,
    conversation_id: conversationId,
    account_id: accountId,
    channel: channel
  }
};
